export async function withRuntime<T>(
  cell: PgLabCell,
  role: DatabaseRole,
  run: (connection: Awaited<ReturnType<PostgresConnectionFactory>>) => Promise<T>,
): Promise<T> {
  const connection = await cell.runtime(role);
  try {
    return await run(connection);
  } finally {
    await connection.end();
  }
}
